#!/bin/bash
# Production-build the supervisor web UI and package a debug APK.
set -euo pipefail

ROOT="$(cd "$(dirname "$0")/.." && pwd)"
ANDROID_DIR="${ROOT}/android-supervisor-app"
ASSETS_DIR="${ANDROID_DIR}/app/src/main/assets/www"
VERSION="$("$(dirname "$0")/read-android-version.sh" "${ANDROID_DIR}/app/build.gradle")"
VERSION_TS="${ROOT}/src/lib/native-app-version.ts"
API_ORIGIN="$(node "$(dirname "$0")/../../scripts/read-client-config.js" apiOrigin)"

echo "==> Syncing app version ${VERSION} into web bundle..."
cat > "$VERSION_TS" <<EOF
/** Generated by scripts/build-android-apk.sh — do not edit */
export const FIELD_TEAM_APP_VERSION = '${VERSION}';
export const OBSERVER_APP_VERSION = '1.0.6';
EOF

echo "==> Building production frontend bundle..."
cd "$ROOT"
VITE_DISABLE_PWA=true npm run build

echo "==> Syncing blocked-app package map..."
mkdir -p "${ANDROID_DIR}/app/src/main/assets"
cp "${ROOT}/shared/blocked-app-packages.json" "${ANDROID_DIR}/app/src/main/assets/blocked-app-packages.json"

echo "==> Syncing dist/ into Android assets..."
rm -rf "$ASSETS_DIR"
mkdir -p "$ASSETS_DIR"
cp -R dist/. "$ASSETS_DIR/"

echo "==> Building Android APK..."
cd "$ANDROID_DIR"

if [ -z "${JAVA_HOME:-}" ]; then
  if [ -d "/Applications/Android Studio.app/Contents/jbr/Contents/Home" ]; then
    export JAVA_HOME="/Applications/Android Studio.app/Contents/jbr/Contents/Home"
  fi
fi

./gradlew assembleDebug -PAPI_ORIGIN="$API_ORIGIN"

APK_PATH="${ANDROID_DIR}/app/build/outputs/apk/debug/app-debug.apk"
STAMPED_APK="${ROOT}/FlexHRM-FieldTeam-v${VERSION}.apk"
cp "$APK_PATH" "$STAMPED_APK"

echo ""
echo "APK ready:"
echo "  ${APK_PATH}"
echo "  ${STAMPED_APK}"
